{"implementation": "def solve(case):
    import math

    payload = case.get('payload')
    if not isinstance(payload, dict):
        raise ValueError('Missing or invalid payload')

    segments_raw = payload.get('segments')
    if not isinstance(segments_raw, list):
        raise ValueError('Missing or invalid segments')

    budget = payload.get('budget')
    if not isinstance(budget, int):
        raise ValueError('Missing or invalid budget')

    # Validate each segment
    for seg in segments_raw:
        if not isinstance(seg, dict):
            raise ValueError('Segment must be a dict')
        for key in ('name', 'importance', 'minimum', 'capacity'):
            if key not in seg:
                raise ValueError(f'Missing key {key} in segment')
            if not isinstance(seg[key], int):
                raise ValueError(f'{key} must be int')
        if seg['minimum'] < 1:
            raise ValueError('Minimum must be >=1')
        if seg['capacity'] < seg['minimum']:
            raise ValueError('Capacity must be >= minimum')

    # Extract segment data, preserve order
    segments = []
    for idx, seg in enumerate(segments_raw):
        segments.append({
            'name': seg['name'],
            'importance': seg['importance'],
            'minimum': seg['minimum'],
            'capacity': seg['capacity'],
            'allocation': seg['minimum'],
            'index': idx
        })

    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)

    if budget < total_min:
        raise ValueError('Budget below sum of minima')
    if budget > total_cap:
        raise ValueError('Budget above total capacity')

    remaining = budget - total_min

    while remaining > 0:
        best_idx = None
        best_score = -float('inf')
        best_orig_index = None

        for i, s in enumerate(segments):
            if s['allocation'] >= s['capacity']:
                continue
            # next position is allocation+1
            score = s['importance'] / (s['allocation'] + 1)
            # tie-break by original segment order (index)
            if score > best_score or (score == best_score and s['index'] < best_orig_index):
                best_score = score
                best_idx = i
                best_orig_index = s['index']

        if best_idx is None:
            # Should not happen because budget <= total_cap
            raise ValueError('Unexpected: no segment with capacity left')

        segments[best_idx]['allocation'] += 1
        remaining -= 1

    # Build output
    allocations = {}
    segment_list = []
    total_allocated = 0
    for s in segments:
        allocations[s['name']] = s['allocation']
        segment_list.append({
            'name': s['name'],
            'importance': s['importance'],
            'minimum': s['minimum'],
            'capacity': s['capacity'],
            'allocated': s['allocation']
        })
        total_allocated += s['allocation']

    return {
        'allocations': allocations,
        'segments': segment_list,
        'total_allocated': total_allocated
    }"}
